import type { Book, BookStatus } from '../../types';

export const STATUS_LABELS: Record<BookStatus, string> = {
  reading: 'Reading',
  'to-read': 'To Read',
  read: 'Read',
  dnf: 'Did Not Finish',
};

export const SKELETON_COUNT = 6;

export function statusColor(status: BookStatus): string {
  switch (status) {
    case 'reading':
      return 'status-reading';
    case 'to-read':
      return 'status-to-read';
    case 'read':
      return 'status-read';
    case 'dnf':
      return 'status-dnf';
  }
}

interface StatusListProps {
  // null signals loading state; array (possibly empty) signals loaded
  items: Book[] | null;
}

function SkeletonItem(): JSX.Element {
  return (
    <li className="status-list-item status-list-item--skeleton">
      <span className="skeleton-title" />
      <span className="skeleton-author" />
    </li>
  );
}

function groupByStatus(items: Book[]): Map<BookStatus, Book[]> {
  const order: BookStatus[] = ['reading', 'to-read', 'read', 'dnf'];
  const map = new Map<BookStatus, Book[]>(order.map((s) => [s, []]));
  for (const item of items) {
    map.get(item.status)?.push(item);
  }
  return map;
}

export function StatusList({ items }: StatusListProps): JSX.Element {
  if (items === null) {
    return (
      <ul className="status-list" aria-busy="true" aria-label="Loading books">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <SkeletonItem key={i} />
        ))}
      </ul>
    );
  }

  const groups = groupByStatus(items);

  return (
    <div className="status-list-groups">
      {Array.from(groups.entries()).map(([status, books]) => {
        if (books.length === 0) {
          return null;
        }
        return (
          <section key={status} className={`status-group status-group--${statusColor(status)}`}>
            <h2 className="status-group-heading">{STATUS_LABELS[status]}</h2>
            <ul className="status-list">
              {books.map((book) => (
                <li key={book.id} className="status-list-item">
                  <span className="status-list-item-title">{book.title}</span>
                  <span className="status-list-item-author">{book.author}</span>
                </li>
              ))}
            </ul>
          </section>
        );
      })}
    </div>
  );
}

