import { useState } from 'react';

const CHIPS = ['All', 'Active', 'Archived', 'Starred'] as const;
type ChipLabel = (typeof CHIPS)[number];

// Owns only visual pressed state; grid filtering is not wired.
const chipFilterStyles = `
@layer components {
  .chip-filter {
    display: flex;
    gap: var(--space-2);
    flex-wrap: wrap;
  }

  .chip-filter-button {
    display: inline-flex;
    align-items: center;
    padding: var(--space-1) var(--space-3);
    border-radius: var(--border-radius-lg);
    border: var(--border-width) solid var(--color-border);
    background-color: var(--color-surface);
    color: var(--color-text-secondary);
    font-size: var(--font-size-sm);
    font-weight: var(--font-weight-medium);
    line-height: var(--line-height-normal);
    cursor: pointer;
    transition:
      background-color var(--duration-fast) var(--easing-standard),
      color var(--duration-fast) var(--easing-standard),
      border-color var(--duration-fast) var(--easing-standard);
  }

  .chip-filter-button:hover {
    background-color: var(--color-surface-subtle);
    color: var(--color-text-primary);
  }

  .chip-filter-button:focus-visible {
    outline-offset: var(--space-1);
    outline: var(--border-width) solid var(--color-text-primary);
  }

  .chip-filter-button[aria-pressed='true'] {
    background-color: var(--color-text-primary);
    color: var(--color-surface);
    border-color: var(--color-text-primary);
  }
}
`;

interface ChipFilterProps {
  onFilterChange?: (filter: ChipLabel) => void;
}

export function ChipFilter({ onFilterChange }: ChipFilterProps): JSX.Element {
  const [active, setActive] = useState<ChipLabel>('All');

  function handleClick(chip: ChipLabel): void {
    setActive(chip);
    onFilterChange?.(chip);
  }

  return (
    <>
      <style>{chipFilterStyles}</style>
      <div className="chip-filter" role="group" aria-label="Filter books">
        {CHIPS.map((chip) => (
          <button
            key={chip}
            type="button"
            className="chip-filter-button"
            aria-pressed={active === chip}
            onClick={() => handleClick(chip)}
          >
            {chip}
          </button>
        ))}
      </div>
    </>
  );
}

