import { useEffect, useState } from 'react';
import './TaskBoard.css';
import { getTasks } from '../../api';
import type { Task } from '../../types';

const SKELETON_COUNT = 3;

function renderList(tasks: Task[]): JSX.Element {
  if (tasks.length === 0) {
    return <p className="task-board-empty">No tasks yet.</p>;
  }
  return (
    <ul className="task-board-list">
      {tasks.map((task) => (
        <li key={task.id} className="task-board-item">
          {task.title}
        </li>
      ))}
    </ul>
  );
}

function renderSkeletons(): JSX.Element {
  return (
    <ul className="task-board-list">
      {Array.from({ length: SKELETON_COUNT }, (_, i) => (
        <li key={i} className="task-board-item task-board-skeleton" />
      ))}
    </ul>
  );
}

export function TaskBoard(): JSX.Element {
  // null = loading; array = loaded
  const [tasks, setTasks] = useState<Task[] | null>(null);

  useEffect(() => {
    getTasks()
      .then((data) => setTasks(data))
      .catch(() => setTasks([]));
  }, []);

  const countLabel = tasks !== null ? String(tasks.length) : '';

  return (
    <div className="task-board">
      <header className="task-board-header">
        <h2 className="task-board-heading">Tasks</h2>
        {tasks !== null && (
          <span className="task-board-count">{countLabel}</span>
        )}
      </header>
      <div className="task-board-filter-bar" />
      <div className="task-board-main">
        {tasks === null ? renderSkeletons() : renderList(tasks)}
      </div>
    </div>
  );
}

