import './PriceDisplay.css';

interface PriceDisplayProps {
  /** Price in cents */
  price: number;
  /** Original price in cents, shown with strikethrough when higher than price */
  originalPrice?: number;
}

function formatCents(cents: number): string {
  // Math.ceil avoids under-charging: fractional cents always round up to the next whole cent
  return `$${(Math.ceil(cents) / 100).toFixed(2)}`;
}

export function PriceDisplay({ price, originalPrice }: PriceDisplayProps): JSX.Element {
  if (originalPrice !== undefined && originalPrice > price) {
    return (
      <span className="price-display">
        <span className="price-original">{formatCents(originalPrice)}</span>
        <span className="price-current">{formatCents(price)}</span>
      </span>
    );
  }

  return (
    <span className="price-display">
      <span className="price-current">{formatCents(price)}</span>
    </span>
  );
}
